const row = $input.first().json || {};
const r = row.resultado || { horario_funcionamento: null, aberto_agora: null, petcash: { ativo: false } };
const petcash = r.petcash && r.petcash.ativo ? {
  ativo: true,
  percentual_cashback: r.petcash.percentual_cashback,
  validade_dias: r.petcash.validade_dias,
  uso_maximo_percentual_por_pedido: r.petcash.uso_maximo_percentual_por_pedido,
  pedido_minimo_para_usar: r.petcash.pedido_minimo_para_usar,
  observacao: r.petcash.observacao,
} : { ativo: false };
return [{ json: {
  horario_funcionamento: r.horario_funcionamento,
  aberto_agora: r.aberto_agora,
  petcash,
} }];

function tryGet(name) {
  try { return $(name).item.json; } catch (e) { return null; }
}
const trigger = $('When Executed by Another Workflow').item.json;
const resultado = tryGet('Montar Resultado');
return [{ json: {
  empresa_id: trigger.p_empresa_id,
  conversa_id: trigger.p_conversa_id || null,
  mensagem_id: trigger.p_mensagem_id || null,
  atendimento_id: trigger.p_atendimento_id || null,
  tool_nome: 'informar_dados_loja',
  detalhes: JSON.stringify({ input: {}, output: resultado }),
  resultado_original: resultado,
} }];

